<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import { listarGaleria, listarUnidadesEvidencia, registrarEvidencia, type Evidencia, type UnidadEvidencia } from '../services/evidencias'
const records=ref<UnidadEvidencia[]>([]),query=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),galleryModal=ref(false),current=ref<UnidadEvidencia|null>(null),file=ref<File|null>(null),preview=ref(''),comment=ref(''),location=reactive<{latitud:number|null;longitud:number|null;status:string}>({latitud:null,longitud:null,status:'Sin solicitar'}),gallery=ref<Evidencia[]>([]),galleryPage=ref(1),galleryLast=ref(1),summary=reactive({total:0,total_evidencias:0,sin_evidencias:0})
async function load(){loading.value=true;error.value='';try{const r=await listarUnidadesEvidencia(query.value);records.value=r.data;Object.assign(summary,{total:r.total,total_evidencias:r.total_evidencias,sin_evidencias:r.sin_evidencias})}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(unit:UnidadEvidencia){current.value=unit;file.value=null;clearPreview();comment.value='';Object.assign(location,{latitud:null,longitud:null,status:'Solicitando ubicación…'});modal.value=true;if(!navigator.geolocation){location.status='GPS no disponible';return}navigator.geolocation.getCurrentPosition(p=>Object.assign(location,{latitud:p.coords.latitude,longitud:p.coords.longitude,status:'Ubicación capturada'}),()=>{location.status='Continuará sin ubicación GPS'},{enableHighAccuracy:true,timeout:8000})}
function selected(event:Event){const selected=(event.target as HTMLInputElement).files?.[0]??null;if(!selected)return;if(!selected.type.startsWith('image/')){error.value='Seleccione un archivo de imagen.';return}if(selected.size>10*1024*1024){error.value='La imagen no puede superar 10 MB.';return}clearPreview();file.value=selected;preview.value=URL.createObjectURL(selected)}function clearPreview(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';file.value=null}
async function save(){if(!current.value||!file.value){error.value='Seleccione una fotografía para registrar.';return}saving.value=true;try{await registrarEvidencia(current.value,file.value,comment.value,location.latitud,location.longitud);modal.value=false;clearPreview();success.value=`Evidencia registrada para ${current.value.placa}.`;await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
async function showGallery(unit:UnidadEvidencia,page=1){current.value=unit;loading.value=true;try{const r=await listarGaleria(unit.id_programacion,unit.id_cisterna,page);gallery.value=r.data;galleryPage.value=r.pagination.current_page;galleryLast.value=r.pagination.last_page;galleryModal.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
const size=()=>file.value?`${(file.value.size/1024/1024).toFixed(2)} MB`:'';const clear=()=>{query.value='';load()};const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(load);onUnmounted(clearPreview)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Gestión de Cisternas / Evidencias</nav><header class="hero"><div class="mark">EV</div><div><small>DANA · GESTIÓN DE CISTERNAS</small><h1>Evidencias de programación</h1><p>Registra fotografías georreferenciadas de las unidades asignadas al conductor.</p></div><button @click="load">↻ Actualizar</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="summary"><article><small>UNIDADES DE HOY</small><b>{{summary.total}}</b></article><article><small>EVIDENCIAS REGISTRADAS</small><b>{{summary.total_evidencias}}</b></article><article><small>SIN EVIDENCIAS</small><b>{{summary.sin_evidencias}}</b></article></section><form class="filters" @submit.prevent="load"><label>Buscar cisterna<input v-model.trim="query" placeholder="Número de placa"></label><button>Buscar</button><button v-if="query" type="button" class="soft" @click="clear">Limpiar</button></form><div v-if="loading" class="empty">Consultando programaciones del día…</div><div v-else-if="!records.length" class="empty">No se encontraron programaciones asignadas para el día de hoy.</div><section v-else class="cards"><article v-for="item in records" :key="item.id_programacion_cisterna"><header><div class="truck">▰</div><div><small>PROGRAMACIÓN #{{item.id_programacion}}</small><h2>{{item.placa}}</h2></div><span>ACTIVO</span></header><div class="person"><small>CONDUCTOR</small><b>{{item.conductor||'—'}}</b></div><section class="kpis"><div><small>EVIDENCIAS</small><b>{{item.evidencias}}</b><button @click="showGallery(item)">Ver galería</button></div><div><small>VUELTA EJECUTADA</small><b>{{item.numero_vueltas_confirmadas}}</b></div></section><p>{{item.ultima_evidencia?`Última evidencia: ${item.ultima_evidencia}`:'Sin actividad fotográfica'}}</p><button class="capture" @click="open(item)">Registrar evidencia</button></article></section>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{current?.placa}} · VUELTA {{current?.numero_vueltas_confirmadas}}</small><h2>Registrar evidencia fotográfica</h2></div><button type="button" @click="modal=false">×</button></header><label class="drop"><input type="file" accept="image/*" capture="environment" @change="selected"><template v-if="!preview"><b>Seleccionar fotografía</b><span>JPG, PNG o imagen desde cámara · máximo 10 MB</span></template><img v-else :src="preview" alt="Vista previa"></label><div v-if="file" class="file"><span><b>{{file.name}}</b><small>{{size()}}</small></span><button type="button" @click="clearPreview">Quitar</button></div><label>Comentario<textarea v-model.trim="comment" rows="3" maxlength="500" placeholder="Descripción opcional de la evidencia"></textarea></label><div class="gps" :class="{ok:location.latitud!==null}"><b>{{location.status}}</b><span v-if="location.latitud!==null">{{location.latitud.toFixed(6)}}, {{location.longitud?.toFixed(6)}}</span></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving||!file">{{saving?'Subiendo…':'Registrar evidencia'}}</button></footer></form></div>
<div v-if="galleryModal" class="backdrop" @mousedown.self="galleryModal=false"><section class="dialog gallery"><header><div><small>{{current?.placa}} · PROGRAMACIÓN #{{current?.id_programacion}}</small><h2>Galería de evidencias</h2></div><button @click="galleryModal=false">×</button></header><div v-if="!gallery.length" class="gallery-empty">No hay evidencias registradas.</div><div v-else class="photos"><article v-for="item in gallery" :key="item.id"><a :href="item.imagen" target="_blank"><img :src="item.imagen" alt="Evidencia"></a><div><b>Vuelta {{item.vuelta}}</b><span>{{item.fecha}} · {{item.hora}}</span><small>{{item.gps?'Con ubicación GPS':'Sin ubicación GPS'}}</small><a v-if="item.descarga" :href="item.descarga">Descargar</a></div></article></div><footer v-if="galleryLast>1"><button :disabled="galleryPage===1" @click="showGallery(current!,galleryPage-1)">Anterior</button><span>Página {{galleryPage}} de {{galleryLast}}</span><button :disabled="galleryPage===galleryLast" @click="showGallery(current!,galleryPage+1)">Siguiente</button></footer></section></div></div></template>
